import java.util.*;

public class MinimumWindowSubstring {
    public String minWindow(String s, String t) {
        if (s.length() < t.length()) return "";

        int[] need = new int[128]; // need[c] > 0 表示还需要，<= 0 表示已满足
        for (char c : t.toCharArray()) {
            need[c]++;
        }

        int left = 0;
        int missing = t.length(); // 还需要匹配的字符总数
        int minLen = Integer.MAX_VALUE;
        int minStart = 0;

        for (int right = 0; right < s.length(); right++) {
            // 加入 s[right]
            char rc = s.charAt(right);
            if (need[rc] > 0) {
                missing--; // 加入前还需要，现在少了一个缺口
            }
            need[rc]--;

            // missing == 0：窗口已覆盖 t，尝试收缩
            while (missing == 0) {
                // 更新最短答案
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minStart = left;
                }
                // 移除 s[left]
                char lc = s.charAt(left);
                need[lc]++;
                if (need[lc] > 0) {
                    missing++; // 移除后又不够了
                }
                left++;
            }
        }
        return minLen == Integer.MAX_VALUE ? "" : s.substring(minStart, minStart + minLen);
    }
}

// 面试时快速手写的精简版，只保留核心逻辑
public String minWindow(String s, String t) {
    int[] need = new int[128];
    for (char c : t.toCharArray()) need[c]++;

    int left = 0, missing = t.length(), minLen = Integer.MAX_VALUE, minStart = 0;
    for (int right = 0; right < s.length(); right++) {
        if (need[s.charAt(right)]-- > 0) missing--; // 合并：先检查再减

        while (missing == 0) { // 窗口覆盖 t
            if (right - left + 1 < minLen) {
                minLen = right - left + 1;
                minStart = left;
            }
            if (++need[s.charAt(left)] > 0) missing++; // 合并：先加再检查
            left++;
        }
    }
    return minLen == Integer.MAX_VALUE ? "" : s.substring(minStart, minStart + minLen);
}
